package com.botw.ui;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Reading the points a creator typed into the leaderboard's edit boxes.
 */
public class ChallengeViewTest
{
	@Test
	public void readsAWholeNumber()
	{
		assertEquals(Integer.valueOf(0), ChallengeView.parsePoints("0"));
		assertEquals(Integer.valueOf(42), ChallengeView.parsePoints("42"));
	}

	@Test
	public void toleratesTheSpaceSomeoneLeavesBehind()
	{
		assertEquals(Integer.valueOf(7), ChallengeView.parsePoints("  7 "));
	}

	/** Docking points is a real thing a clan does, so a minus sign is not a mistake. */
	@Test
	public void allowsNegatives()
	{
		assertEquals(Integer.valueOf(-5), ChallengeView.parsePoints("-5"));
	}

	/**
	 * Null means "tell them, and send nothing". Guessing a number out of "12 points" or treating an
	 * empty box as zero would quietly set someone's score to something they did not type.
	 */
	@Test
	public void refusesAnythingThatIsNotOne()
	{
		assertNull(ChallengeView.parsePoints(""));
		assertNull(ChallengeView.parsePoints("   "));
		assertNull(ChallengeView.parsePoints("ten"));
		assertNull(ChallengeView.parsePoints("12 points"));
		assertNull(ChallengeView.parsePoints("3.5"));
		assertNull(ChallengeView.parsePoints("1,000"));
	}
}

package com.botw.ui;

import java.awt.BorderLayout;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class BotwPanelTest
{
	@Test
	public void scoreStaysInsideSidebarWhenVerticalScrollbarAppears() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			BotwPanel.SidebarContent content = new BotwPanel.SidebarContent();
			content.setLayout(new BorderLayout());
			content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

			JPanel rows = new JPanel();
			rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
			rows.setPreferredSize(new Dimension(260, 720));
			JLabel firstScore = null;
			JPanel firstRow = null;
			for (int i = 0; i < 30; i++)
			{
				JPanel row = new JPanel(new BorderLayout());
				row.add(new JLabel("Cast Revelio"), BorderLayout.CENTER);
				JLabel score = new JLabel("100 pts");
				row.add(score, BorderLayout.EAST);
				row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
				rows.add(row);
				if (firstRow == null)
				{
					firstRow = row;
					firstScore = score;
				}
			}

			JPanel screen = new JPanel(new BorderLayout());
			screen.add(rows, BorderLayout.NORTH);
			content.add(screen, BorderLayout.NORTH);

			JScrollPane scroll = new JScrollPane(content,
				JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
			scroll.setSize(225, 180);
			scroll.doLayout();
			scroll.getViewport().doLayout();
			content.doLayout();
			screen.doLayout();
			rows.doLayout();
			firstRow.doLayout();

			assertTrue(scroll.getVerticalScrollBar().isVisible());
			assertEquals(scroll.getViewport().getWidth(), content.getWidth());
			assertTrue(firstScore.getX() + firstScore.getWidth() <= firstRow.getWidth());
		});
	}
}

package com.botw.data;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Working out which pet dropped, which the game does not say.
 */
public class BossDropsTest
{
	private static final Set<String> PETS =
		new HashSet<>(Arrays.asList("vorki", "olmlet", "little nightmare", "beaver"));

	@Test
	public void thePetIsTheOneThePlayersAreCompetingFor()
	{
		assertEquals("Vorki", BossDrops.petIn(challenge(
			new DropRule("Draconic visage", 11286, 100),
			new DropRule("Vorki", 21992, 500)), PETS));
	}

	/**
	 * Typed by the creator rather than filled in from the bundled list, which is what happens at every
	 * raid — the wiki gave those bosses no uniques, so their pets are always hand-typed.
	 */
	@Test
	public void aHandTypedPetCountsTheSame()
	{
		assertEquals("olmlet", BossDrops.petIn(challenge(new DropRule("olmlet", -1, 400)), PETS));
	}

	@Test
	public void aChallengeThatCountsNoPetHasNone()
	{
		assertNull(BossDrops.petIn(challenge(new DropRule("Draconic visage", 11286, 100)), PETS));
		assertNull(BossDrops.petIn(challenge(), PETS));
		assertNull(BossDrops.petIn(null, PETS));
	}

	/** A pet on the list for nothing is a pet the creator took off it. */
	@Test
	public void aPetWorthNothingIsNotCounted()
	{
		assertNull(BossDrops.petIn(challenge(new DropRule("Vorki", 21992, 0)), PETS));
	}

	/**
	 * No boss drops two pets, so this is a challenge nobody will run — but guessing between them would
	 * be inventing a drop, and scoring nothing is the honest answer.
	 */
	@Test
	public void twoPetsCannotBeToldApart()
	{
		assertNull(BossDrops.petIn(challenge(
			new DropRule("Vorki", 21992, 500),
			new DropRule("Little nightmare", 24491, 500)), PETS));
	}

	private static Challenge challenge(DropRule... drops)
	{
		Challenge challenge = new Challenge();
		challenge.setCode("VORK01");
		challenge.setDrops(drops.length == 0 ? Collections.emptyList() : Arrays.asList(drops));
		return challenge;
	}
}

package com.botw.net;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Telling "there is no such challenge" apart from "I could not ask".
 */
public class BotwApiTest
{
	/**
	 * The distinction the whole thing turns on.
	 * <p>
	 * A challenge that is gone gets cleared off the player's list and its queued events thrown away.
	 * Doing that to one that merely could not be reached would delete somebody's competition because
	 * their connection dropped for a moment, so an ordinary failure must never look gone.
	 */
	@Test
	public void onlyAnAnswerOfNoSuchThingCountsAsGone()
	{
		assertTrue(BotwApi.Result.gone("No challenge with that code").isGone());

		assertFalse(BotwApi.Result.failed("Could not reach the server").isGone());
		assertFalse(BotwApi.Result.failed("The server said no (500)").isGone());
		assertFalse(BotwApi.Result.failed("The server sent something unreadable").isGone());
	}

	@Test
	public void goneIsStillAFailure()
	{
		assertFalse(BotwApi.Result.gone("No challenge with that code").ok());
	}

	@Test
	public void aSuccessIsNeitherFailedNorGone()
	{
		BotwApi.Result<String> result = BotwApi.Result.of("fine");
		assertTrue(result.ok());
		assertFalse(result.isGone());
	}
}

package com.botw.track;

import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The rules that decide whether something counts, all of which have been wrong at some point.
 */
public class KillTrackerTest
{
	/**
	 * The bug this was written for: one Scurrius, two kills.
	 * <p>
	 * The Loot Tracker re-announces every NPC kill as a {@code LootReceived}, so a plugin listening to
	 * both events sees an ordinary boss twice. Counting it here would double every kill count in the
	 * competition for everyone running the Loot Tracker, which is the default.
	 */
	@Test
	public void npcLootIsLeftToTheOtherListener()
	{
		assertFalse(KillTracker.countsAsKill(LootRecordType.NPC));
	}

	/** Chest payouts are the whole reason this event is listened to; nothing else reports a raid. */
	@Test
	public void chestPayoutsCount()
	{
		assertTrue(KillTracker.countsAsKill(LootRecordType.EVENT));
	}

	@Test
	public void killingPeopleAndRobbingThemAreNotBossKills()
	{
		assertFalse(KillTracker.countsAsKill(LootRecordType.PLAYER));
		assertFalse(KillTracker.countsAsKill(LootRecordType.PICKPOCKET));
	}

	@Test
	public void bossNamesMatchWhateverTheGameCallsThem()
	{
		assertTrue(KillTracker.matches("Scurrius", "Scurrius"));
		assertTrue(KillTracker.matches("scurrius", "SCURRIUS"));

		// The game adds a form or a level in brackets; the challenge does not.
		assertTrue(KillTracker.matches("Dagannoth Rex", "Dagannoth Rex (Level 303)"));
		assertTrue(KillTracker.matches("Kalphite Queen (Second form)", "Kalphite Queen"));
	}

	/**
	 * All three, because the third is the bug that started this.
	 * <p>
	 * A clan member killed the boss with a full inventory and a pet already following them, so theirs
	 * went to Probita and the game said "would have been followed" rather than "being followed".
	 * Reading only the usual message would have gone on missing exactly that case.
	 */
	@Test
	public void everyWayThePetCanArriveIsAPet()
	{
		assertTrue(KillTracker.isPetMessage("You have a funny feeling like you're being followed."));
		assertTrue(KillTracker.isPetMessage("You feel something weird sneaking into your backpack."));
		assertTrue(KillTracker.isPetMessage("You have a funny feeling like you would have been followed."));
	}

	@Test
	public void ordinaryChatIsNotAPet()
	{
		assertFalse(KillTracker.isPetMessage("You have a funny feeling like you forgot to bank."));
		assertFalse(KillTracker.isPetMessage("Your Vorkath kill count is: 500."));
		assertFalse(KillTracker.isPetMessage(null));
	}

	/**
	 * A pet is announced without a boss attached, so the only thing tying it to the challenge is when
	 * it happened. Both orders count: ordinarily the pet lands first, but the raids announce it at the
	 * end of the raid and do not pay out until the chest is opened.
	 */
	@Test
	public void aPetBelongsToAKillOnEitherSideOfIt()
	{
		long now = 1_700_000_000_000L;

		assertTrue(KillTracker.fromTheSameKill(now, now));
		assertTrue(KillTracker.fromTheSameKill(now, now + 2_000));
		assertTrue(KillTracker.fromTheSameKill(now, now - 45_000));

		// Cutting yews an hour into the week is not a boss pet.
		assertFalse(KillTracker.fromTheSameKill(now, now - 3_600_000));
		assertFalse(KillTracker.fromTheSameKill(now, now + 3_600_000));

		// Nothing has happened yet, which pairs with nothing.
		assertFalse(KillTracker.fromTheSameKill(0, now));
		assertFalse(KillTracker.fromTheSameKill(now, 0));
	}

	@Test
	public void oneBossIsNotAnother()
	{
		assertFalse(KillTracker.matches("Scurrius", "Giant rat"));
		assertFalse(KillTracker.matches("Zulrah", null));
		assertFalse(KillTracker.matches(null, "Zulrah"));

		// A prefix is not a match without the bracket: the King Black Dragon is not a black dragon.
		assertFalse(KillTracker.matches("Black dragon", "Black dragon guard"));
	}
}

package com.botw.track;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * How wide the creator's copy comes out, which decides whether the game's own text can be read in it.
 */
public class ScreenshotterTest
{
	@Test
	public void anOrdinaryClientIsBarelyShrunk()
	{
		// 1080p, the common case. Measured at this width, the drop message and the mouse tooltip read
		// cleanly; the 600 this used to be did not.
		assertEquals(1520, Screenshotter.targetWidth(1920));
	}

	@Test
	public void asmallClientIsLeftAlone()
	{
		// Nothing is gained by shrinking something already smaller than the target, and enlarging it
		// would cost bytes for detail that is not there.
		assertEquals(1280, Screenshotter.targetWidth(1280));
		assertEquals(800, Screenshotter.targetWidth(800));
	}

	/**
	 * The reason there is a floor as well as a target.
	 * <p>
	 * The game draws its text at a fixed pixel size whatever the window is, so legibility follows how
	 * far the picture is shrunk. Holding a big client to 1520 would more than halve it and take the
	 * writing with it.
	 */
	@Test
	public void aBigClientIsNotForcedDownToTheTarget()
	{
		assertEquals(1920, Screenshotter.targetWidth(2560));
		assertEquals(2880, Screenshotter.targetWidth(3840));
	}

	@Test
	public void nothingIsEverEnlarged()
	{
		for (int width : new int[]{320, 765, 1280, 1600, 1920, 2560, 3440, 3840, 5120})
		{
			assertTrue("enlarged a " + width + "px client", Screenshotter.targetWidth(width) <= width);
		}
	}
}

package com.botw;

import com.botw.net.BotwApi;
import com.botw.track.Screenshotter;
import com.botw.ui.BotwPanel;
import com.botw.track.ChallengeStore;
import com.botw.track.EventSender;
import com.botw.track.KillTracker;
import com.botw.track.Outbox;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Boss of the Week",
	description = "Run and track clan Boss of the Week challenges",
	tags = {"boss", "clan", "event", "competition", "leaderboard", "drops", "kc"}
)
public class BotwPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private ChallengeStore challenges;

	@Inject
	private Outbox outbox;

	@Inject
	private KillTracker killTracker;

	@Inject
	private EventSender sender;

	@Inject
	private BotwPanel panel;

	@Inject
	private Screenshotter screenshotter;

	@Inject
	private BotwApi api;

	@Inject
	private BotwConfig config;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ClientToolbar clientToolbar;

	private NavigationButton navigationButton;

	@Provides
	BotwConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BotwConfig.class);
	}

	@Override
	protected void startUp()
	{
		// The tracker is registered by hand rather than being a plugin of its own, so that it stops
		// listening the moment this plugin is switched off.
		eventBus.register(killTracker);

		challenges.load();
		outbox.load();

		panel.setPlayerName(this::localPlayerName);

		// The panel refreshes itself once points land, so an open leaderboard catches up without the
		// player pressing anything.
		sender.setOnSent(panel::onPointsSent);
		sender.start();

		// Evidence goes to the creator on a background thread. Best effort by design: the full-size
		// copy is already on the player's disk, so a failed upload costs a thumbnail rather than proof.
		screenshotter.setUploader((code, eventId, itemName, jpeg) -> executor.execute(() ->
		{
			String token = challenges.participantTokenFor(code);
			if (token == null)
			{
				return;
			}

			BotwApi.Result<BotwApi.Snapshot> result = api.uploadShot(
				config.serverUrl(), code, token, eventId, itemName, System.currentTimeMillis(), jpeg);

			if (!result.ok())
			{
				log.debug("Could not upload evidence for {}: {}", itemName, result.getError());
			}
		}));

		navigationButton = NavigationButton.builder()
			.tooltip("Boss of the Week")
			.icon(icon())
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown()
	{
		sender.stop();
		eventBus.unregister(killTracker);
		clientToolbar.removeNavigation(navigationButton);
	}

	/**
	 * The sidebar icon. Drawn rather than shipped as a file so there is one less thing to get wrong in
	 * the plugin hub's packaging.
	 */
	private BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(220, 138, 0));
		graphics.fillOval(1, 1, 14, 14);
		graphics.setColor(new Color(40, 40, 40));
		graphics.setFont(new Font("SansSerif", Font.BOLD, 10));
		graphics.drawString("B", 5, 12);
		graphics.dispose();
		return image;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// Both are stored per account, so they cannot be read until there is an account to read them
		// for. Logging in on a second character has to swap them over, not merge them.
		challenges.load();
		outbox.load();

		// And the panel has to be told. It is built at start-up, before there is an account, so without
		// this it goes on showing the empty list it was born with until something else happens to
		// rebuild it — which is why the challenges only turned up after a trip through Create or Join.
		panel.refreshList();

		// A backlog from an earlier session goes out now rather than waiting for the next timer.
		sender.flush();
	}

	/**
	 * The name points are reported under. Null until logged in, which is why nothing is sent before
	 * then — a kill by "nobody" cannot be put on a leaderboard.
	 */
	public String localPlayerName()
	{
		return client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName();
	}
}

package com.botw.ui;

import com.botw.BotwFiles;
import com.botw.net.BotwApi;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Image;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;
import javax.imageio.ImageIO;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;

/**
 * The evidence, for whoever is running the challenge.
 * <p>
 * A folder per participant, because that is the question people actually ask: not "what happened this
 * week" but "show me this person's drops". Folded shut to begin with, since a fifty-person clan is
 * fifty folders and nobody wants to scroll past forty-nine of them.
 * <p>
 * Pictures are fetched only when a folder is opened. A hundred thumbnails at once would be several
 * megabytes for a screen most of which is never looked at.
 */
@Slf4j
public class EvidencePanel extends JPanel
{
	private static final DateTimeFormatter WHEN =
		DateTimeFormatter.ofPattern("d MMM, HH:mm").withZone(ZoneId.systemDefault());

	private final String challengeCode;
	private final String challengeName;
	private final String creatorToken;
	private final String serverUrl;
	private final BotwApi api;
	private final ScheduledExecutorService executor;

	private final Map<String, List<BotwApi.Shot>> byParticipant = new LinkedHashMap<>();
	private final java.util.Set<String> open = new java.util.HashSet<>();

	/**
	 * @param participants everyone who has joined, so each gets a folder whether or not they have
	 *                     anything in it yet. A folder that only appears once someone scores looks like
	 *                     a missing feature rather than an empty one.
	 */
	public EvidencePanel(
		String challengeCode,
		String challengeName,
		String creatorToken,
		String serverUrl,
		BotwApi api,
		ScheduledExecutorService executor,
		List<com.botw.data.LeaderboardEntry> participants)
	{
		this.challengeCode = challengeCode;
		this.challengeName = challengeName;
		this.creatorToken = creatorToken;
		this.serverUrl = serverUrl;
		this.api = api;
		this.executor = executor;

		// Seeded empty so every participant has a folder from the moment they join.
		for (com.botw.data.LeaderboardEntry entry : participants)
		{
			byParticipant.put(entry.getRsn(), new ArrayList<>());
		}

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(Theme.BACKGROUND);
		setAlignmentX(Component.LEFT_ALIGNMENT);

		add(loading());
		load();
	}

	private void load()
	{
		executor.execute(() ->
		{
			BotwApi.Result<List<BotwApi.Shot>> result =
				api.listShots(serverUrl, challengeCode, creatorToken);

			SwingUtilities.invokeLater(() ->
			{
				removeAll();

				if (!result.ok())
				{
					add(muted(result.getError()));
					revalidate();
					repaint();
					return;
				}

				// The seeded folders stay; the shots fill them in.
				for (List<BotwApi.Shot> shots : byParticipant.values())
				{
					shots.clear();
				}

				for (BotwApi.Shot shot : result.getValue())
				{
					byParticipant.computeIfAbsent(shot.getRsn(), rsn -> new ArrayList<>()).add(shot);
				}

				rebuild();
			});
		});
	}

	private void rebuild()
	{
		removeAll();

		if (byParticipant.isEmpty())
		{
			add(muted("Nobody has joined yet. Share the code and their folders will appear here."));
		}

		for (Map.Entry<String, List<BotwApi.Shot>> entry : byParticipant.entrySet())
		{
			add(folder(entry.getKey(), entry.getValue()));
			add(Cards.gap(3));
		}

		revalidate();
		repaint();
	}

	/** One participant, shut until asked for. */
	private JPanel folder(String rsn, List<BotwApi.Shot> shots)
	{
		JPanel wrapper = new JPanel();
		wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
		wrapper.setBackground(Theme.BACKGROUND);
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setBackground(Theme.CARD);
		header.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		boolean opened = open.contains(rsn);

		JLabel name = new JLabel((opened ? "− " : "+ ") + rsn);
		name.setFont(Theme.heading());
		name.setForeground(Theme.GOLD);
		header.add(name, BorderLayout.CENTER);

		JLabel count = new JLabel(shots.isEmpty()
			? "none yet"
			: shots.size() + (shots.size() == 1 ? " drop" : " drops"));
		count.setFont(Theme.body());
		count.setForeground(Theme.TEXT_MUTED);
		header.add(count, BorderLayout.EAST);

		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent event)
			{
				if (opened)
				{
					open.remove(rsn);
				}
				else
				{
					open.add(rsn);
				}

				rebuild();
			}
		});

		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, header.getPreferredSize().height));
		wrapper.add(header);

		if (opened)
		{
			if (shots.isEmpty())
			{
				wrapper.add(Cards.gap(2));
				wrapper.add(muted("No screenshots yet."));
			}

			for (BotwApi.Shot shot : shots)
			{
				wrapper.add(Cards.gap(2));
				wrapper.add(shotRow(shot));
			}

			if (!shots.isEmpty())
			{
				wrapper.add(Cards.gap(4));
				wrapper.add(exportButton(rsn, shots));
			}
		}

		return wrapper;
	}

	/**
	 * One drop, with its picture fetched as the row is built.
	 */
	private JPanel shotRow(BotwApi.Shot shot)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 8));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());

		JLabel item = new JLabel(shot.getItemName());
		item.setFont(Theme.body());
		item.setForeground(Theme.TEXT);
		item.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(item);

		JLabel when = new JLabel(WHEN.format(Instant.ofEpochMilli(shot.getOccurredAt())));
		when.setFont(Theme.body());
		when.setForeground(Theme.TEXT_MUTED);
		when.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(when);

		row.add(text, BorderLayout.NORTH);

		JLabel picture = new JLabel("loading…");
		picture.setFont(Theme.body());
		picture.setForeground(Theme.TEXT_MUTED);
		row.add(picture, BorderLayout.CENTER);

		executor.execute(() ->
		{
			BotwApi.Result<byte[]> image =
				api.readShot(serverUrl, challengeCode, creatorToken, shot.getEventId());

			SwingUtilities.invokeLater(() ->
			{
				if (!image.ok())
				{
					picture.setText(image.getError());
					return;
				}

				try
				{
					// Scaled to the panel's width. The stored copy is far wider than the sidebar, on
					// purpose — this is a preview, and the export is where the full detail is read.
					Image full = ImageIO.read(new ByteArrayInputStream(image.getValue()));
					int width = Math.max(80, getWidth() - 40);
					int height = full.getHeight(null) * width / Math.max(1, full.getWidth(null));

					picture.setText(null);
					picture.setIcon(new ImageIcon(
						full.getScaledInstance(width, height, Image.SCALE_SMOOTH)));

					row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
					row.revalidate();
				}
				catch (IOException | RuntimeException e)
				{
					picture.setText("Could not read that screenshot");
				}
			});
		});

		return row;
	}

	/**
	 * Everything one participant has, written to a zip.
	 * <p>
	 * Clan leaders pass these between themselves to settle an argument, and a folder full of loose
	 * images is not something anyone can hand over in one go.
	 */
	private JButton exportButton(String rsn, List<BotwApi.Shot> shots)
	{
		JButton export = Cards.button("Export " + rsn + "'s drops");
		export.setAlignmentX(Component.LEFT_ALIGNMENT);
		export.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

		export.addActionListener(event ->
		{
			export.setEnabled(false);
			export.setText("Exporting…");

			executor.execute(() ->
			{
				File written = exportZip(rsn, shots);

				SwingUtilities.invokeLater(() ->
				{
					export.setEnabled(true);
					export.setText("Export " + rsn + "'s drops");

					if (written == null)
					{
						Cards.warn(this, "Could not write that export.");
						return;
					}

					reveal(written);
				});
			});
		});

		return export;
	}

	private File exportZip(String rsn, List<BotwApi.Shot> shots)
	{
		File folder = BotwFiles.exports();
		if (!folder.exists() && !folder.mkdirs())
		{
			log.warn("Could not make the export folder {}", folder);
			return null;
		}

		File zip = new File(folder, safe(challengeName) + " - " + safe(rsn) + ".zip");

		try (ZipOutputStream out = new ZipOutputStream(new FileOutputStream(zip)))
		{
			int written = 0;

			for (BotwApi.Shot shot : shots)
			{
				BotwApi.Result<byte[]> image =
					api.readShot(serverUrl, challengeCode, creatorToken, shot.getEventId());

				if (!image.ok())
				{
					// One unreadable picture should not lose the other nineteen.
					log.debug("Skipping {} in the export: {}", shot.getEventId(), image.getError());
					continue;
				}

				String name = WHEN.format(Instant.ofEpochMilli(shot.getOccurredAt()))
					.replace(':', '-').replace(',', ' ')
					+ " " + safe(shot.getItemName()) + ".jpg";

				out.putNextEntry(new ZipEntry(name));
				out.write(image.getValue());
				out.closeEntry();
				written++;
			}

			log.debug("Exported {} screenshots to {}", written, zip);
			return zip;
		}
		catch (IOException e)
		{
			log.warn("Could not write the export", e);
			return null;
		}
	}

	/**
	 * Says where the export went, and puts the path on the clipboard so it can be pasted straight into
	 * a file browser.
	 * <p>
	 * It would be nicer to open the folder, and this did. Both ways of doing that — AWT's
	 * {@code Desktop} and RuneLite's {@code LinkBrowser} — are restricted on the plugin hub, because
	 * handing a local path to the system to open is handing it something to execute. Copying the path
	 * is the way round it that the hub's maintainers point people to, and it costs the reader one
	 * paste.
	 */
	private void reveal(File zip)
	{
		String path = zip.getAbsolutePath();

		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new StringSelection(path), null);

			Cards.warn(this, "Saved to " + path + System.lineSeparator()
				+ System.lineSeparator() + "The path is on your clipboard.");
		}
		catch (RuntimeException e)
		{
			// A clipboard can be unavailable or held by something else. The path is the point, so it
			// is still shown; only the convenience is lost.
			log.debug("Could not copy the export path", e);
			Cards.warn(this, "Saved to " + path);
		}
	}

	private static String safe(String name)
	{
		String cleaned = name == null ? "" : name.replaceAll("[\\\\/:*?\"<>|]", "-").trim();
		return cleaned.isEmpty() ? "Unnamed" : cleaned;
	}

	private JPanel loading()
	{
		JPanel panel = new JPanel();
		panel.setBackground(Theme.BACKGROUND);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(muted("Loading evidence…"));
		return panel;
	}

	private JLabel muted(String text)
	{
		JLabel label = new JLabel("<html><body style='width:165px'>" + text + "</body></html>");
		label.setFont(Theme.body());
		label.setForeground(Theme.TEXT_MUTED);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}
}

package com.botw.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.BorderFactory;
import javax.swing.JTextField;
import javax.swing.border.Border;
import net.runelite.client.ui.FontManager;

/**
 * The look of the thing.
 * <p>
 * RuneLite's own palette is flat grey on flat grey, which is right for a tool you glance at and wrong
 * for something people open to see whether they are winning. This is a darker, slightly blue base with
 * gold on top of it — gold because that is what a scoreboard is, and because it reads as a prize
 * rather than as an interface.
 * <p>
 * Kept in one place so a colour can be changed once rather than in nine panels.
 */
public final class Theme
{
	/** Near-black with a little blue in it. Flat grey is what made the first attempt look dreary. */
	public static final Color BACKGROUND = new Color(24, 25, 31);

	/** Cards sit just above the background rather than being outlined, which is quieter and reads better. */
	public static final Color CARD = new Color(35, 37, 46);
	public static final Color CARD_HOVER = new Color(45, 48, 60);

	/** The prize colour. Used for anything that is a score, a code, or a call to action. */
	public static final Color GOLD = new Color(240, 176, 62);
	public static final Color GOLD_DIM = new Color(150, 110, 40);

	/** For a challenge that is live right now. */
	public static final Color LIVE = new Color(93, 200, 120);

	public static final Color TEXT = new Color(228, 228, 232);
	public static final Color TEXT_MUTED = new Color(150, 152, 163);

	private Theme()
	{
	}

	/**
	 * The plugin's own name, larger than anything else on the panel.
	 */
	public static Font title()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 22f);
	}

	/** The label on a tile button. Big enough to read without looking for it. */
	public static Font tile()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 15f);
	}

	public static Font heading()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 14f);
	}

	public static Font body()
	{
		return FontManager.getRunescapeSmallFont();
	}

	/**
	 * A number worth looking at — a score, a countdown, a challenge code.
	 */
	public static Font figure(float size)
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, size);
	}

	/**
	 * Swing draws a text field white unless told otherwise, which is where the bright box in the
	 * middle of a dark panel came from.
	 */
	public static JTextField textField(JTextField field)
	{
		field.setBackground(CARD);
		field.setForeground(TEXT);
		field.setCaretColor(GOLD);
		field.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(58, 61, 74)),
			BorderFactory.createEmptyBorder(4, 6, 4, 6)));
		field.setFont(body());
		return field;
	}

	public static Border cardBorder()
	{
		return BorderFactory.createEmptyBorder(8, 10, 8, 10);
	}

	/**
	 * Turns antialiasing on before anything is drawn by hand. Without it the rounded corners look
	 * chewed.
	 */
	public static Graphics2D smooth(Graphics2D graphics)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		return graphics;
	}
}

package com.botw.ui;

import com.botw.BotwConfig;
import com.botw.data.BossDrops;
import com.botw.data.Challenge;
import com.botw.data.LeaderboardEntry;
import com.botw.net.BotwApi;
import com.botw.track.ChallengeStore;
import com.botw.track.EventSender;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar.
 * <p>
 * Three screens behind one panel: the list of challenges this account is in, the form for making one,
 * and one challenge open. A sidebar is too narrow to show more than one at a time, and tabs across the
 * top would spend a quarter of the width saying which of three things you are looking at.
 * <p>
 * Every call to the service happens on the executor and comes back through the EDT. A request on the
 * client thread freezes the game, and a request on the EDT freezes the panel while it waits.
 */
@Singleton
public class BotwPanel extends PluginPanel
{
	private final ChallengeStore challenges;
	private final BossDrops bossDrops;
	private final BotwApi api;
	private final BotwConfig config;
	private final ItemManager itemManager;
	private final ScheduledExecutorService executor;
	private final EventSender sender;

	/** The logged-in name, which is who points are reported as. Null until logged in. */
	private Supplier<String> playerName = () -> null;

	private final JPanel content = new SidebarContent();

	/** Keep every screen within the viewport when a vertical scrollbar takes up sidebar width. */
	static final class SidebarContent extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	@Inject
	private BotwPanel(
		ChallengeStore challenges,
		BossDrops bossDrops,
		BotwApi api,
		BotwConfig config,
		ItemManager itemManager,
		ScheduledExecutorService executor,
		EventSender sender)
	{
		super(false);

		this.challenges = challenges;
		this.bossDrops = bossDrops;
		this.api = api;
		this.config = config;
		this.itemManager = itemManager;
		this.executor = executor;
		this.sender = sender;

		setLayout(new BorderLayout());
		setBackground(Theme.BACKGROUND);
		setOpaque(true);

		// PluginPanel pads itself, and that padding paints in whatever the panel's background is —
		// which is where the pale frame around everything came from. Removed here and put back inside
		// the scroll pane, so the dark goes right to the edge.
		setBorder(BorderFactory.createEmptyBorder());

		content.setLayout(new BorderLayout());
		content.setBackground(Theme.BACKGROUND);
		content.setOpaque(true);
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JScrollPane scroll = new JScrollPane(
			content, JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setBackground(Theme.BACKGROUND);
		scroll.setOpaque(true);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setBackground(Theme.BACKGROUND);
		scroll.getViewport().setBackground(Theme.BACKGROUND);
		scroll.getViewport().setOpaque(true);
		add(scroll, BorderLayout.CENTER);

		showList();
	}

	public void setPlayerName(Supplier<String> playerName)
	{
		this.playerName = playerName;
	}

	/**
	 * Called once this client's points have reached the service, so what is on screen catches up
	 * without anyone pressing anything.
	 * <p>
	 * Both screens that show points have to be handled, which is the bug this was written for: only the
	 * list was, so with a challenge open you could kill something, watch the screenshot appear in the
	 * evidence, and see your score sit still until you pressed Refresh.
	 * <p>
	 * The forms are still left alone. Rebuilding a half-filled one under someone's hands would throw
	 * away what they had typed.
	 */
	public void onPointsSent()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (content.getComponentCount() == 0)
			{
				return;
			}

			Component screen = content.getComponent(0);

			if (screen instanceof ListView)
			{
				showList();
				return;
			}

			if (!(screen instanceof ChallengeView))
			{
				return;
			}

			ChallengeView view = (ChallengeView) screen;
			if (view.isEditingLeaderboard())
			{
				return;
			}

			String code = view.getChallengeCode();

			executor.execute(() ->
			{
				BotwApi.Result<BotwApi.Snapshot> result = api.read(config.serverUrl(), code);
				if (!result.ok())
				{
					// Silent on purpose. This runs on a timer nobody asked for, and a warning box every
					// minute the connection hiccups would be worse than a leaderboard a minute behind.
					return;
				}

				SwingUtilities.invokeLater(() ->
				{
					// Still the same screen? A minute is long enough to have gone somewhere else.
					if (content.getComponentCount() > 0 && content.getComponent(0) == view)
					{
						view.update(result.getValue().getLeaderboard());
					}
				});
			});
		});
	}

	/**
	 * Redraws the list of challenges, if that is what is on screen.
	 * <p>
	 * Used after logging in, when the saved challenges become readable for the first time.
	 */
	public void refreshList()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (content.getComponentCount() > 0 && content.getComponent(0) instanceof ListView)
			{
				showList();
			}
		});
	}

	/**
	 * Re-reads the saved challenges, then brings each one up to date from the service.
	 * <p>
	 * The local half is what the button is really for. Challenges are saved against the logged-in
	 * account, so before login there is nothing to read and the list is empty; this is how it fills in
	 * without the player having to leave the screen and come back.
	 * <p>
	 * The service is then asked about each one, because the creator may have renamed it, moved its
	 * dates or changed what things are worth since it was last looked at. That half is done off the
	 * EDT, and the list is drawn once without waiting for it, so the button always feels immediate.
	 */
	private void reloadList()
	{
		challenges.load();
		showList();

		List<String> codes = new ArrayList<>();
		for (ChallengeStore.Membership membership : challenges.all())
		{
			codes.add(membership.challenge.getCode());
		}

		if (codes.isEmpty())
		{
			return;
		}

		executor.execute(() ->
		{
			List<Challenge> fresh = new ArrayList<>();
			for (String code : codes)
			{
				BotwApi.Result<BotwApi.Snapshot> result = api.read(config.serverUrl(), code);

				// A challenge that cannot be reached is left exactly as it was. A moment without a
				// network is not evidence that a challenge is gone, and dropping it would take the
				// player's tokens with it.
				if (result.ok() && result.getValue().getChallenge() != null)
				{
					fresh.add(result.getValue().getChallenge());
				}
			}

			SwingUtilities.invokeLater(() ->
			{
				for (Challenge challenge : fresh)
				{
					// Tokens survive this: a read carries the challenge, never the secrets.
					challenges.put(challenge, null, null);
				}

				refreshList();
			});
		});
	}

	private void show(JPanel screen)
	{
		content.removeAll();
		content.add(screen, BorderLayout.NORTH);
		content.revalidate();
		content.repaint();
	}

	/** Marker so {@link #refreshList()} can tell which screen is up without tracking state. */
	private static class ListView extends JPanel
	{
	}

	private void showList()
	{
		ListView list = new ListView();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(Theme.BACKGROUND);

		JLabel heading = new JLabel("BOSS OF THE WEEK");
		heading.setFont(Theme.title());
		heading.setForeground(Theme.GOLD);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		list.add(heading);

		JLabel strapline = new JLabel("Clan challenges, counted for you");
		strapline.setFont(Theme.body());
		strapline.setForeground(Theme.TEXT_MUTED);
		strapline.setAlignmentX(Component.LEFT_ALIGNMENT);
		list.add(strapline);

		list.add(Cards.gap(12));

		list.add(new TileButton("Create a challenge", "Pick a boss and set the points", this::showCreate));
		list.add(Cards.gap(8));
		list.add(new TileButton("Join a challenge", "Enter a code from your clan", this::showJoin));

		list.add(Cards.gap(14));

		// The heading and its reload are outside the empty check on purpose. An empty list is the case
		// that most needs reloading — before logging in there is nothing saved to read — and a button
		// that appears only once it is no longer needed would be no use at all.
		list.add(listHeader());

		List<ChallengeStore.Membership> mine = new ArrayList<>(challenges.all());
		if (mine.isEmpty())
		{
			list.add(Cards.gap(4));
			list.add(muted("Nothing yet. Make a challenge, or join one with a code. "
				+ "If you have joined one already, log in and press Reload."));
		}
		else
		{
			for (ChallengeStore.Membership membership : mine)
			{
				list.add(Cards.gap(4));
				list.add(challengeCard(membership));
			}
		}

		show(list);
	}

	/**
	 * Joining, once the tile has been pressed. A code box that is only there when it is wanted, rather
	 * than a field sitting on the front screen for the one time in twenty it gets used.
	 */
	private void showJoin()
	{
		JPanel screen = new JPanel();
		screen.setLayout(new BoxLayout(screen, BoxLayout.Y_AXIS));
		screen.setBackground(Theme.BACKGROUND);

		JLabel heading = new JLabel("JOIN A CHALLENGE");
		heading.setFont(Theme.figure(18f));
		heading.setForeground(Theme.GOLD);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		screen.add(heading);

		screen.add(Cards.gap(10));
		screen.add(muted("Paste the code the challenge's creator gave you."));
		screen.add(Cards.gap(8));

		JTextField code = Theme.textField(new JTextField());
		code.setAlignmentX(Component.LEFT_ALIGNMENT);
		code.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
		code.setFont(Theme.figure(16f));
		code.setHorizontalAlignment(JTextField.CENTER);
		screen.add(code);

		screen.add(Cards.gap(10));
		screen.add(new TileButton("Join", null, () -> join(code.getText().trim().toUpperCase())));

		screen.add(Cards.gap(8));
		JButton back = Cards.button("← Back");
		back.addActionListener(event -> showList());
		screen.add(back);

		show(screen);

		// The code box is the only thing on this screen, so put the cursor in it.
		SwingUtilities.invokeLater(code::requestFocusInWindow);
	}

	/**
	 * "Your challenges", with the reload beside it rather than below, so it costs no vertical room in a
	 * sidebar that has none to spare.
	 */
	private JPanel listHeader()
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		row.add(sectionLabel("Your challenges"), BorderLayout.WEST);

		JButton reload = Cards.button("Reload");
		reload.setToolTipText("Re-read your saved challenges and check them against the server");
		reload.addActionListener(event -> reloadList());
		row.add(reload, BorderLayout.EAST);

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text.toUpperCase());
		label.setFont(Theme.body());
		label.setForeground(Theme.TEXT_MUTED);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private JLabel muted(String text)
	{
		JLabel label = new JLabel("<html><body style='width:165px'>" + text + "</body></html>");
		label.setFont(Theme.body());
		label.setForeground(Theme.TEXT_MUTED);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private JPanel challengeCard(ChallengeStore.Membership membership)
	{
		Challenge challenge = membership.challenge;

		JPanel card = new JPanel(new BorderLayout(4, 0));
		card.setBackground(Theme.CARD);
		card.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(card.getBackground());

		JLabel name = new JLabel(challenge.getName());
		name.setFont(Theme.heading());
		name.setForeground(Theme.TEXT);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(name);

		text.add(Cards.mutedInRow(challenge.getBoss()));
		text.add(Cards.mutedInRow(Countdown.describe(challenge, System.currentTimeMillis())));

		// Which side of the challenge this account is on, said on the card rather than only inside.
		// Being both is normal now: you make a challenge, then join it on the account you play.
		String role;
		if (membership.isCreator() && membership.isParticipant())
		{
			role = "CREATOR · JOINED";
		}
		else if (membership.isCreator())
		{
			role = "CREATOR · NOT JOINED";
		}
		else
		{
			role = "PARTICIPANT";
		}

		JLabel tag = new JLabel(role);
		tag.setFont(Theme.body());
		tag.setForeground(membership.isCreator() ? Theme.GOLD : Theme.TEXT_MUTED);
		tag.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(tag);

		card.add(text, BorderLayout.CENTER);

		JButton open = Cards.button("Open");
		open.addActionListener(event -> openChallenge(challenge.getCode()));
		card.add(open, BorderLayout.EAST);

		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	private void showCreate()
	{
		show(new CreatePanel(bossDrops, itemManager, this::create, this::showList));
	}

	private void showEdit(Challenge challenge)
	{
		show(new CreatePanel(bossDrops, itemManager, this::saveEdit,
			() -> openChallenge(challenge.getCode()), challenge));
	}

	private void saveEdit(Challenge challenge)
	{
		String token = challenges.creatorTokenFor(challenge.getCode());
		if (token == null)
		{
			Cards.warn(this, "Only the creator can change this challenge.");
			return;
		}

		busy("Saving…");
		executor.execute(() ->
		{
			BotwApi.Result<BotwApi.Snapshot> result =
				api.update(config.serverUrl(), challenge, token);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					Cards.warn(this, result.getError());
				}
				else
				{
					challenges.put(result.getValue().getChallenge(), null, null);
				}

				openChallenge(challenge.getCode());
			});
		});
	}

	private void delete(String code)
	{
		String token = challenges.creatorTokenFor(code);
		if (token == null)
		{
			Cards.warn(this, "Only the creator can delete this challenge.");
			return;
		}

		busy("Deleting…");
		executor.execute(() ->
		{
			BotwApi.Result<BotwApi.Snapshot> result = api.delete(config.serverUrl(), code, token);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					showList();
					Cards.warn(this, result.getError());
					return;
				}

				// Locally too, along with anything still waiting to be sent for it — there is nothing
				// left to send it to.
				challenges.remove(code);
				sender.forget(code);
				showList();
			});
		});
	}

	private void create(Challenge challenge)
	{
		String rsn = playerName.get();
		if (rsn == null)
		{
			Cards.warn(this, "Log in first — a challenge is created under your name.");
			return;
		}

		busy("Creating…");
		executor.execute(() ->
		{
			BotwApi.Result<BotwApi.Snapshot> result = api.create(config.serverUrl(), challenge, rsn);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					showList();
					Cards.warn(this, result.getError());
					return;
				}

				BotwApi.Snapshot snapshot = result.getValue();

				// Only the creator token. Making a challenge and competing in it are separate things,
				// and joining is what a client needs to report kills — so the creator joins with the
				// code like everybody else, on whichever account they are actually playing.
				challenges.put(snapshot.getChallenge(), snapshot.getCreatorToken(), null);

				openChallenge(snapshot.getChallenge().getCode());
			});
		});
	}

	private void join(String code)
	{
		if (code.isEmpty())
		{
			Cards.warn(this, "Paste the challenge code first.");
			return;
		}

		String rsn = playerName.get();
		if (rsn == null)
		{
			Cards.warn(this, "Log in first — you join under your own name.");
			return;
		}

		busy("Joining…");
		executor.execute(() ->
		{
			BotwApi.Result<BotwApi.Snapshot> result = api.join(config.serverUrl(), code, rsn);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					showList();
					Cards.warn(this, result.getError());
					return;
				}

				BotwApi.Snapshot snapshot = result.getValue();
				challenges.put(snapshot.getChallenge(), null, snapshot.getParticipantToken());
				openChallenge(snapshot.getChallenge().getCode());
			});
		});
	}

	private void openChallenge(String code)
	{
		openChallenge(code, false);
	}

	/**
	 * @param asPlayer draw it the way a participant sees it, even for the creator. Whoever runs a
	 *                 challenge holds its creator token and so can never reach the plain screen on
	 *                 their own account — they get the dashboard even after joining — which leaves
	 *                 them unable to see what they are asking their clan to use.
	 */
	private void openChallenge(String code, boolean asPlayer)
	{
		busy("Loading…");

		executor.execute(() ->
		{
			// Sent before read, so opening a challenge or pressing Refresh shows the kill that has just
			// happened. Reading first would show the board as it was before this client had said
			// anything, which is a refresh that appears not to work — press it, see the old number,
			// press it again, see the old number.
			sender.flush();

			BotwApi.Result<BotwApi.Snapshot> result = api.read(config.serverUrl(), code);

			SwingUtilities.invokeLater(() ->
			{
				ChallengeStore.Membership membership = challenges.find(code);

				if (result.isGone())
				{
					// The service answered and said there is no such challenge: it was deleted by whoever
					// ran it, or it never existed. Keeping it on the list means a card that cannot be
					// opened and cannot be got rid of, so this is the one case where removing it is
					// offered. Offered, not done — it is the player's list.
					forget(code, membership);
					return;
				}

				if (!result.ok())
				{
					// Fall back to what is stored rather than showing nothing. Someone on a train can
					// still check when their challenge ends. Deliberately kept: a challenge that could
					// not be reached is not a challenge that is gone.
					if (membership != null)
					{
						show(new ChallengeView(membership.challenge, new ArrayList<>(), playerName.get(),
							membership.isCreator(), itemManager, this::showList, () -> openChallenge(code)));
					}
					else
					{
						showList();
					}

					Cards.warn(this, result.getError());
					return;
				}

				BotwApi.Snapshot snapshot = result.getValue();
				challenges.put(snapshot.getChallenge(), null, null);

				// Everything the creator gets hangs off this one token, so the preview is simply this
				// being treated as absent. That is what makes it an honest preview rather than a
				// separate screen that could drift out of step with the real one.
				String creatorToken = asPlayer ? null : challenges.creatorTokenFor(code);

				JPanel evidence = creatorToken == null
					? null
					: new EvidencePanel(code, snapshot.getChallenge().getName(), creatorToken,
						config.serverUrl(), api, executor, snapshot.getLeaderboard());

				Challenge open = snapshot.getChallenge();
				boolean canPreview = !asPlayer && challenges.creatorTokenFor(code) != null;

				show(new ChallengeView(
					open,
					snapshot.getLeaderboard(),
					playerName.get(),
					!asPlayer && membership != null && membership.isCreator(),
					itemManager,
					this::showList,
					() -> openChallenge(code, asPlayer),
					evidence,
					creatorToken == null ? null : () -> showEdit(open),
					creatorToken == null ? null : () -> delete(code),
					creatorToken == null ? null : leaderboardEditor(code, creatorToken),
					canPreview ? () -> openChallenge(code, true) : null,
					asPlayer ? () -> openChallenge(code, false) : null));
			});
		});
	}

	/**
	 * The creator's three edits to the leaderboard, each of which reopens the challenge on the way back
	 * so the board they are looking at is the one the service now holds rather than the one they were
	 * looking at a moment ago.
	 */
	private ChallengeView.LeaderboardEditor leaderboardEditor(String code, String creatorToken)
	{
		return new ChallengeView.LeaderboardEditor()
		{
			@Override
			public void add(String rsn, int points)
			{
				run("Adding " + rsn + "…",
					() -> api.addParticipant(config.serverUrl(), code, creatorToken, rsn, points));
			}

			@Override
			public void setPoints(Map<String, Integer> changes)
			{
				// One request per changed player, run in order on the one thread. The service has no
				// endpoint that takes several at once, and firing them off in parallel would race each
				// other's recomputation of the same leaderboard.
				run("Saving…", () ->
				{
					BotwApi.Result<BotwApi.Snapshot> result = null;

					for (Map.Entry<String, Integer> change : changes.entrySet())
					{
						result = api.setPoints(
							config.serverUrl(), code, creatorToken, change.getKey(), change.getValue());

						// Stopped at the first refusal, so the creator is told which name failed rather
						// than being shown the last one's error for all of them.
						if (!result.ok())
						{
							break;
						}
					}

					return result;
				});
			}

			@Override
			public void remove(String rsn)
			{
				run("Removing " + rsn + "…",
					() -> api.removeParticipant(config.serverUrl(), code, creatorToken, rsn));
			}

			private void run(String message, Supplier<BotwApi.Result<BotwApi.Snapshot>> call)
			{
				busy(message);
				executor.execute(() ->
				{
					BotwApi.Result<BotwApi.Snapshot> result = call.get();

					SwingUtilities.invokeLater(() ->
					{
						// Null only if there was nothing to send, which the caller already rules out.
						if (result != null && !result.ok())
						{
							Cards.warn(BotwPanel.this, result.getError());
						}

						// Reopened either way. After a failure the board on screen is still right, and
						// after a success it is the only way to see the new one.
						openChallenge(code);
					});
				});
			}
		};
	}

	/**
	 * Offers to take a challenge that no longer exists off this account's list.
	 * <p>
	 * Also throws away anything still queued for it. Those events can never be delivered — there is
	 * nothing left to deliver them to — and without this they would be retried every minute for as long
	 * as the plugin is installed.
	 */
	private void forget(String code, ChallengeStore.Membership membership)
	{
		String name = membership == null ? code : membership.challenge.getName();

		int answer = JOptionPane.showConfirmDialog(
			this,
			"\"" + name + "\" no longer exists on the server." + System.lineSeparator()
				+ System.lineSeparator()
				+ "Whoever ran it has deleted it. Remove it from your list?",
			"Boss of the Week",
			JOptionPane.YES_NO_OPTION);

		if (answer == JOptionPane.YES_OPTION)
		{
			challenges.remove(code);
			sender.forget(code);
		}

		showList();
	}

	private void busy(String message)
	{
		JPanel waiting = new JPanel();
		waiting.setLayout(new BoxLayout(waiting, BoxLayout.Y_AXIS));
		waiting.setBackground(Theme.BACKGROUND);
		waiting.add(muted(message));
		show(waiting);
	}
}

package com.botw.ui;

import com.botw.data.BossDrops;
import com.botw.data.Challenge;
import com.botw.data.DropRule;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JTextField;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.http.api.item.ItemPrice;

/**
 * Setting up a challenge.
 * <p>
 * The list of drops fills itself in from the chosen boss, because typing out sixteen items and their
 * point values is the sort of chore that stops people running events at all. Everything about it is
 * then editable — the inferred list gets the pets and the visages right and lets the odd bolt tip
 * through, so an X on every row matters more than the guess being perfect.
 */
public class CreatePanel extends JPanel
{
	private static final DateTimeFormatter ENTERED = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

	/** Offered first because they are where the clan is. Any zone can still be typed. */
	private static final String[] COMMON_ZONES = {
		"Australia/Brisbane", "Australia/Sydney", "Australia/Perth",
		"Europe/London", "America/New_York", "America/Los_Angeles", "UTC"
	};

	private final BossDrops bossDrops;
	private final ItemManager itemManager;

	private final JTextField name = new JTextField();
	private final JTextField startsAt = new JTextField();
	private final JTextField endsAt = new JTextField();
	private final JComboBox<String> timezone = Cards.comboBox(COMMON_ZONES);

	private final JTextField bossSearch = new JTextField();
	private final JComboBox<BossDrops.Boss> bossPicker = Cards.comboBox(new BossDrops.Boss[0]);

	private final JSpinner kcPer = new JSpinner(new SpinnerNumberModel(10, 1, 10000, 1));
	private final JSpinner kcPoints = new JSpinner(new SpinnerNumberModel(1, 0, 10000, 1));

	/** The drop list being built, in the order it will be shown. Keyed by name, which is what scores. */
	private final Map<String, DropRule> drops = new LinkedHashMap<>();
	private final JPanel dropList = new JPanel();

	private final JPanel chosenBoss = new JPanel();
	private final JTextField itemSearch = new JTextField();
	private final JPanel itemResults = new JPanel();

	private final Consumer<Challenge> onCreate;
	private final Runnable onCancel;

	/** Set when changing an existing challenge rather than making one. */
	private Challenge editing;

	public CreatePanel(
		BossDrops bossDrops, ItemManager itemManager, Consumer<Challenge> onCreate, Runnable onCancel)
	{
		this(bossDrops, itemManager, onCreate, onCancel, null);
	}

	/**
	 * @param editing an existing challenge to change, or null to make a new one. The same form either
	 *                way — the fields are identical, and a second panel would be one more thing to keep
	 *                in step with this one.
	 */
	public CreatePanel(
		BossDrops bossDrops, ItemManager itemManager, Consumer<Challenge> onCreate, Runnable onCancel,
		Challenge editing)
	{
		this.bossDrops = bossDrops;
		this.itemManager = itemManager;
		this.onCreate = onCreate;
		this.onCancel = onCancel;

		setLayout(new BorderLayout());
		setBackground(Theme.BACKGROUND);

		JPanel form = new JPanel();
		form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
		form.setBackground(Theme.BACKGROUND);
		form.setBorder(BorderFactory.createEmptyBorder(4, 0, 8, Cards.SCROLLBAR_ALLOWANCE));

		JLabel heading = new JLabel(editing == null ? "NEW CHALLENGE" : "EDIT CHALLENGE");
		heading.setFont(Theme.figure(18f));
		heading.setForeground(Theme.GOLD);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		form.add(heading);
		form.add(Cards.gap(10));

		form.add(Cards.field("Challenge name", field(name)));
		form.add(Cards.gap(8));

		// Written out rather than picked from a calendar: a text field is one line of code and one
		// line of instruction, and a date picker in a 225px sidebar is neither.
		form.add(Cards.field("Starts (yyyy-mm-dd hh:mm)", field(startsAt)));
		form.add(Cards.gap(4));
		form.add(Cards.field("Ends (yyyy-mm-dd hh:mm)", field(endsAt)));
		form.add(Cards.gap(4));
		form.add(Cards.field("Timezone", timezone));
		form.add(Cards.gap(8));

		form.add(Cards.field("Find a boss", field(bossSearch)));
		form.add(Cards.gap(4));
		form.add(bossPicker);
		form.add(Cards.gap(6));

		// Without this the search box still reads as a half-finished search once a boss is picked, and
		// nothing on the screen says which one the challenge is actually about.
		chosenBoss.setLayout(new BoxLayout(chosenBoss, BoxLayout.Y_AXIS));
		chosenBoss.setBackground(Theme.BACKGROUND);
		chosenBoss.setAlignmentX(Component.LEFT_ALIGNMENT);
		form.add(chosenBoss);
		form.add(Cards.gap(8));

		form.add(Cards.sectionLabel("Kill count"));
		form.add(everyKillsRow());
		form.add(Cards.gap(8));

		form.add(Cards.sectionLabel("Drops"));
		dropList.setLayout(new BoxLayout(dropList, BoxLayout.Y_AXIS));
		dropList.setBackground(Theme.BACKGROUND);
		dropList.setAlignmentX(Component.LEFT_ALIGNMENT);
		form.add(dropList);
		form.add(Cards.gap(6));

		form.add(Cards.field("Add any item", field(itemSearch)));
		itemResults.setLayout(new BoxLayout(itemResults, BoxLayout.Y_AXIS));
		itemResults.setBackground(Theme.BACKGROUND);
		itemResults.setAlignmentX(Component.LEFT_ALIGNMENT);
		form.add(itemResults);

		form.add(Cards.gap(10));
		form.add(buttons());

		add(form, BorderLayout.NORTH);

		bossSearch.getDocument().addDocumentListener(onType(this::refillBossPicker));
		itemSearch.getDocument().addDocumentListener(onType(this::refillItemResults));
		bossPicker.addActionListener(event ->
		{
			fillDropsFromBoss();
			showChosenBoss();
		});

		refillBossPicker();

		if (editing == null)
		{
			showChosenBoss();
			prefillTimes();
		}
		else
		{
			this.editing = editing;
			fillFrom(editing);
		}
	}

	/**
	 * Puts an existing challenge back into the form.
	 * <p>
	 * The drop list is taken from the challenge rather than from the boss, because the creator has
	 * already made their choices about it and refilling from the boss would throw away every removal
	 * and every points value they had set.
	 */
	private void fillFrom(Challenge challenge)
	{
		name.setText(challenge.getName());
		timezone.setSelectedItem(challenge.getTimezone());
		startsAt.setText(written(challenge.getStartsAt(), challenge.getTimezone()));
		endsAt.setText(written(challenge.getEndsAt(), challenge.getTimezone()));
		kcPer.setValue(Math.max(1, challenge.getKcPer()));
		kcPoints.setValue(Math.max(0, challenge.getKcPoints()));

		bossSearch.setText(challenge.getBoss());
		refillBossPicker();

		// Selecting the boss would refill the drops from the wiki list and undo the creator's edits, so
		// the stored list is put back afterwards.
		drops.clear();
		for (DropRule rule : challenge.getDrops())
		{
			drops.put(rule.getName(), new DropRule(rule.getName(), rule.getItemId(), rule.getPoints()));
		}

		showChosenBoss();
		rebuildDropList();
	}

	private static String written(long epochMillis, String timezone)
	{
		try
		{
			return java.time.Instant.ofEpochMilli(epochMillis)
				.atZone(ZoneId.of(timezone))
				.toLocalDateTime()
				.format(ENTERED);
		}
		catch (RuntimeException e)
		{
			return LocalDateTime.now().format(ENTERED);
		}
	}

	/** "Every [10] kills is worth [1] points", laid out as a row rather than two labelled fields. */
	private JPanel everyKillsRow()
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));

		row.add(small("Every"));
		row.add(spinner(kcPer));
		row.add(small("kills ="));
		row.add(spinner(kcPoints));
		row.add(small("pts"));

		return row;
	}

	private JPanel buttons()
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

		JButton cancel = Cards.button("Cancel");
		cancel.addActionListener(event -> onCancel.run());

		JButton create = Cards.button(editing == null ? "Create challenge" : "Save changes");
		create.addActionListener(event -> submit());

		row.add(cancel);
		row.add(javax.swing.Box.createHorizontalStrut(4));
		row.add(create);
		return row;
	}

	/**
	 * A sensible week, so the common case is two edits rather than two full timestamps typed out.
	 */
	private void prefillTimes()
	{
		LocalDateTime now = LocalDateTime.now();
		startsAt.setText(now.plusDays(1).withHour(10).withMinute(0).format(ENTERED));
		endsAt.setText(now.plusDays(8).withHour(22).withMinute(0).format(ENTERED));
		timezone.setSelectedItem(ZoneId.systemDefault().getId());
	}

	/**
	 * A plain statement of which boss this challenge is about, under the search.
	 */
	private void showChosenBoss()
	{
		chosenBoss.removeAll();

		BossDrops.Boss boss = (BossDrops.Boss) bossPicker.getSelectedItem();
		if (boss != null)
		{
			JPanel card = new JPanel(new BorderLayout());
			card.setBackground(Theme.CARD);
			card.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
			card.setAlignmentX(Component.LEFT_ALIGNMENT);

			JLabel chosen = new JLabel(boss.getName());
			chosen.setFont(Theme.heading());
			chosen.setForeground(Theme.GOLD);
			card.add(chosen, BorderLayout.CENTER);

			card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
			chosenBoss.add(card);
		}

		chosenBoss.revalidate();
		chosenBoss.repaint();
	}

	private void refillBossPicker()
	{
		DefaultComboBoxModel<BossDrops.Boss> model = new DefaultComboBoxModel<>();
		for (BossDrops.Boss boss : bossDrops.search(bossSearch.getText()))
		{
			model.addElement(boss);
		}

		bossPicker.setModel(model);
		if (model.getSize() > 0)
		{
			bossPicker.setSelectedIndex(0);
		}
	}

	/**
	 * Replaces the drop list with whatever the newly chosen boss is known for.
	 * <p>
	 * Replaces rather than merges: changing the boss means the old list is about a different fight, and
	 * quietly leaving Vorkath's visages on a Zulrah challenge would be worse than losing an edit.
	 */
	private void fillDropsFromBoss()
	{
		BossDrops.Boss boss = (BossDrops.Boss) bossPicker.getSelectedItem();
		drops.clear();

		if (boss != null)
		{
			for (BossDrops.Unique unique : boss.getUniques())
			{
				drops.put(unique.getName(),
					new DropRule(unique.getName(), unique.getItemId(), 0));
			}
		}

		rebuildDropList();
	}

	private void rebuildDropList()
	{
		dropList.removeAll();

		if (drops.isEmpty())
		{
			dropList.add(Cards.muted("No drops on this challenge yet. Pick a boss, or add items below."));
		}

		for (DropRule rule : new ArrayList<>(drops.values()))
		{
			dropList.add(dropRow(rule));
			dropList.add(Cards.gap(2));
		}

		dropList.revalidate();
		dropList.repaint();
	}

	/** An icon, the name, a points box, and an X. */
	private JPanel dropRow(DropRule rule)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(4, 5, 4, 5));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 28));
		if (rule.getItemId() > 0)
		{
			itemManager.getImage(rule.getItemId()).addTo(icon);
		}
		row.add(icon, BorderLayout.WEST);

		JLabel label = new JLabel("<html><body style='width:72px'>" + rule.getName() + "</body></html>");
		label.setFont(Theme.body());
		label.setForeground(Theme.TEXT);
		row.add(label, BorderLayout.CENTER);

		JPanel right = new JPanel();
		right.setLayout(new BoxLayout(right, BoxLayout.X_AXIS));
		right.setBackground(row.getBackground());

		JSpinner points = new JSpinner(new SpinnerNumberModel(rule.getPoints(), 0, 100000, 1));
		points.setPreferredSize(new Dimension(46, 20));
		points.setMaximumSize(new Dimension(46, 20));
		points.addChangeListener(event -> rule.setPoints((Integer) points.getValue()));
		right.add(points);

		JButton remove = Cards.button("X");
		remove.setToolTipText("Do not count " + rule.getName());
		remove.addActionListener(event ->
		{
			drops.remove(rule.getName());
			rebuildDropList();
		});
		right.add(remove);

		row.add(right, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/**
	 * Anything at all can be added, not only the boss's own drops. Clans run challenges on all sorts of
	 * things and the inferred list will always miss somebody's idea.
	 */
	private void refillItemResults()
	{
		itemResults.removeAll();

		String query = itemSearch.getText().trim();
		if (query.length() < 3)
		{
			itemResults.revalidate();
			itemResults.repaint();
			return;
		}

		List<ItemPrice> found = itemManager.search(query);
		if (found.isEmpty())
		{
			JLabel none = new JLabel("Nothing matches that.");
			none.setFont(Theme.body());
			none.setForeground(Theme.TEXT_MUTED);
			none.setAlignmentX(Component.LEFT_ALIGNMENT);
			itemResults.add(none);
		}

		int shown = 0;
		for (ItemPrice item : found)
		{
			// Enough to choose from without the panel growing past the screen. The rest are reached by
			// typing more, which is faster than scrolling anyway.
			if (shown++ >= 8)
			{
				break;
			}

			itemResults.add(searchResult(item));
			itemResults.add(Cards.gap(2));
		}

		itemResults.revalidate();
		itemResults.repaint();
	}

	/**
	 * One search result: icon, name, and a row tall enough to hit.
	 * <p>
	 * Was a text button barely taller than its own text, which made the list look broken and gave
	 * nothing to aim at.
	 */
	private JPanel searchResult(ItemPrice item)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 28));
		itemManager.getImage(item.getId()).addTo(icon);
		row.add(icon, BorderLayout.WEST);

		JLabel label = new JLabel("<html><body style='width:120px'>" + item.getName() + "</body></html>");
		label.setFont(Theme.body());
		label.setForeground(Theme.TEXT);
		row.add(label, BorderLayout.CENTER);

		row.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent event)
			{
				drops.put(item.getName(), new DropRule(item.getName(), item.getId(), 0));
				itemSearch.setText("");
				refillItemResults();
				rebuildDropList();
			}

			@Override
			public void mouseEntered(java.awt.event.MouseEvent event)
			{
				row.setBackground(Theme.CARD_HOVER);
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent event)
			{
				row.setBackground(Theme.CARD);
			}
		});

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
		return row;
	}

	private void submit()
	{
		Challenge challenge = new Challenge();
		challenge.setName(name.getText().trim());

		BossDrops.Boss boss = (BossDrops.Boss) bossPicker.getSelectedItem();
		challenge.setBoss(boss == null ? "" : boss.getName());

		String zone = String.valueOf(timezone.getSelectedItem());
		challenge.setTimezone(zone);

		Long start = parse(startsAt.getText(), zone);
		Long end = parse(endsAt.getText(), zone);

		if (challenge.getName().isEmpty() || challenge.getBoss().isEmpty() || start == null || end == null)
		{
			Cards.warn(this, "A name, a boss and both times are needed. Times look like 2026-08-17 10:00.");
			return;
		}

		if (end <= start)
		{
			Cards.warn(this, "The end time has to be after the start time.");
			return;
		}

		challenge.setStartsAt(start);
		challenge.setEndsAt(end);
		challenge.setKcPer((Integer) kcPer.getValue());
		challenge.setKcPoints((Integer) kcPoints.getValue());
		challenge.setDrops(new ArrayList<>(drops.values()));

		// Carried through so the caller knows which challenge it is saving.
		if (editing != null)
		{
			challenge.setCode(editing.getCode());
		}

		onCreate.accept(challenge);
	}

	/**
	 * A typed time, read in the challenge's own timezone rather than the machine's. Someone in Perth
	 * setting up a Brisbane event means the Brisbane hour.
	 */
	private static Long parse(String text, String timezone)
	{
		try
		{
			LocalDateTime local = LocalDateTime.parse(text.trim(), ENTERED);
			return local.atZone(ZoneId.of(timezone)).toInstant().toEpochMilli();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static JTextField field(JTextField field)
	{
		Theme.textField(field);
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		return field;
	}

	private static JSpinner spinner(JSpinner spinner)
	{
		spinner.setPreferredSize(new Dimension(48, 22));
		spinner.setMaximumSize(new Dimension(48, 22));
		return spinner;
	}

	private static JLabel small(String text)
	{
		JLabel label = new JLabel(" " + text + " ");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Theme.TEXT);
		return label;
	}

	private static DocumentListener onType(Runnable action)
	{
		return new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent event)
			{
				action.run();
			}

			@Override
			public void removeUpdate(DocumentEvent event)
			{
				action.run();
			}

			@Override
			public void changedUpdate(DocumentEvent event)
			{
				action.run();
			}
		};
	}
}

package com.botw.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ButtonGroup;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JToggleButton;
import javax.swing.SwingConstants;
import net.runelite.client.ui.FontManager;

/**
 * Shared building blocks, so the panels look like one plugin rather than several.
 * <p>
 * Carried over from GearForge along with the lessons in it: a centred child in a vertical BoxLayout
 * indents everything below it, and text inside a row has to be narrower than the panel or it pushes
 * whatever sits beside it off the edge.
 */
final class Cards
{
	/** Left accent strip width on a card, in pixels. */
	private static final int ACCENT = 3;

	/** Red rather than the brand orange, so a warning does not read as ordinary highlighting. */
	private static final Color WARNING_COLOR = new Color(220, 90, 70);

	/**
	 * Secondary text. RuneLite's MEDIUM_GRAY_COLOR on the panel background is grey-on-grey and was
	 * reported as hard to read; this keeps the hierarchy while staying legible.
	 */
	private static final Color MUTED_TEXT = Theme.TEXT_MUTED;

	/**
	 * Rows sit inside a scroll pane, and a trailing value would otherwise be clipped by the scrollbar.
	 */
	static final int SCROLLBAR_ALLOWANCE = 12;

	private Cards()
	{
	}

	/**
	 * A padded block with a subtle darker background — the unit the panel is composed from.
	 */
	static JPanel card()
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(Theme.CARD);
		card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		return card;
	}

	/**
	 * A card with a coloured strip down the left, used for the headline result.
	 */
	static JPanel accentCard(Color accent)
	{
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(Theme.CARD);
		wrapper.setBorder(BorderFactory.createMatteBorder(0, ACCENT, 0, 0, accent));
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
		return wrapper;
	}

	/**
	 * Section label — small, uppercase, muted. Used to break the panel into scannable groups.
	 */
	static JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text.toUpperCase());
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return label;
	}

	/**
	 * The one number that matters, rendered large.
	 */
	static JLabel headline(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 16f));
		label.setForeground(Theme.GOLD);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A setup or section title — larger than body text so a list of setups scans by name.
	 */
	static JLabel title(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 13f));
		label.setForeground(Theme.TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A prominent warning block — a coloured strip and bold text, for things the player needs to act
	 * on rather than merely notice.
	 */
	static JPanel warning(String text)
	{
		JPanel inner = new JPanel();
		inner.setLayout(new BoxLayout(inner, BoxLayout.Y_AXIS));
		inner.setBackground(Theme.CARD);
		inner.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JLabel label = new JLabel("<html><body style='width:140px'>" + escape(text) + "</body></html>");
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(WARNING_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		inner.add(label);

		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(Theme.CARD);
		card.setBorder(BorderFactory.createMatteBorder(0, ACCENT, 0, 0, WARNING_COLOR));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(inner, BorderLayout.CENTER);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/**
	 * The secondary text colour, for callers that need it on a component this class does not build.
	 */
	static Color mutedColor()
	{
		return MUTED_TEXT;
	}

	/**
	 * Says something went wrong, where the player is already looking. A dialog would take focus off the
	 * game for something as ordinary as a mistyped date.
	 */
	static void warn(java.awt.Component parent, String message)
	{
		javax.swing.JOptionPane.showMessageDialog(
			parent, message, "Boss of the Week", javax.swing.JOptionPane.INFORMATION_MESSAGE);
	}

	static JLabel body(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Theme.TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * Muted, wrapped text for reasons and caveats.
	 */
	/**
	 * Muted text sized to sit inside a row that already has an icon on one side and a value on the
	 * other. The full-width version forces the row wider than the panel, which pushes the value off the
	 * edge entirely.
	 */
	static JLabel mutedInRow(String text)
	{
		JLabel label = new JLabel("<html><body style='width:100px'>" + escape(text) + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	static JLabel muted(String text)
	{
		JLabel label = new JLabel("<html><body style='width:145px'>" + escape(text) + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A labelled form field stacked vertically, which reads better than side-by-side at this width.
	 */
	static JPanel field(String label, JComponent input)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(Theme.BACKGROUND);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel caption = sectionLabel(label);
		panel.add(caption);

		input.setAlignmentX(Component.LEFT_ALIGNMENT);
		input.setMaximumSize(new Dimension(Integer.MAX_VALUE, input.getPreferredSize().height));
		panel.add(input);

		return panel;
	}

	/**
	 * A vertical spacer that is left-aligned like everything else.
	 * <p>
	 * {@link Box#createVerticalStrut} defaults to centre alignment, and a Y_AXIS BoxLayout containing
	 * a mix of alignments indents its children instead of filling the panel — which is what made the
	 * whole sidebar look squashed toward one side.
	 */
	static Component gap(int height)
	{
		Component strut = Box.createVerticalStrut(height);
		((JComponent) strut).setAlignmentX(Component.LEFT_ALIGNMENT);
		return strut;
	}

	/**
	 * A compact button that matches the sidebar rather than the platform look-and-feel.
	 */
	static JButton button(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(Theme.TEXT);
		button.setBackground(Theme.CARD);
		button.setFocusPainted(false);
		button.setBorderPainted(false);
		button.setOpaque(true);
		// Tight horizontal padding: at 225px, three buttons in a row have barely 60px each, and
		// generous padding is what truncated "Off task" into "Off...".
		button.setBorder(BorderFactory.createEmptyBorder(4, 3, 4, 3));
		button.setFocusPainted(false);
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		return button;
	}

	/**
	 * A titled section that expands when clicked, like the panels in the wiki's DPS calculator.
	 * <p>
	 * Used instead of a dropdown where the options benefit from being seen at once — prayers as a grid
	 * of icons, potions as a scrollable list — rather than hidden one-at-a-time behind a combo box.
	 *
	 * @param content shown when expanded; starts hidden
	 * @param decorate given the header button, so callers can hang an icon on it — the sprite and item
	 *                 image loaders are asynchronous, so the icon cannot simply be passed in
	 */
	static JPanel expandable(String title, JComponent content, Consumer<JButton> decorate)
	{
		JPanel section = new JPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setBackground(Theme.BACKGROUND);
		section.setAlignmentX(Component.LEFT_ALIGNMENT);

		JButton header = button(title + "   +");
		header.setHorizontalAlignment(SwingConstants.LEFT);
		header.setIconTextGap(8);
		// Tall enough that a skill icon sits in the row rather than being clipped by it.
		header.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		header.setPreferredSize(new Dimension(0, 30));
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		decorate.accept(header);

		content.setVisible(false);
		content.setAlignmentX(Component.LEFT_ALIGNMENT);

		header.addActionListener(event ->
		{
			boolean opening = !content.isVisible();
			content.setVisible(opening);
			header.setText(title + (opening ? "   −" : "   +"));
			section.revalidate();
			section.repaint();
		});

		section.add(header);
		section.add(content);
		return section;
	}

	/**
	 * A dropdown styled to match the sidebar. The default Swing combo renders light-on-light here and
	 * stands out badly against RuneLite's dark panels.
	 */
	static <T> JComboBox<T> comboBox(T[] items)
	{
		JComboBox<T> combo = new JComboBox<>(items);
		combo.setFont(FontManager.getRunescapeSmallFont());
		combo.setBackground(Theme.CARD);
		combo.setForeground(Theme.TEXT);
		combo.setFocusable(false);
		combo.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
		combo.setRenderer(new DarkListRenderer());
		combo.setAlignmentX(Component.LEFT_ALIGNMENT);
		// Without a maximum, BoxLayout leaves the combo at its preferred width instead of filling.
		combo.setMaximumSize(new Dimension(Integer.MAX_VALUE, combo.getPreferredSize().height));
		return combo;
	}

	/**
	 * Two or more mutually exclusive options as side-by-side buttons — clearer than a dropdown when
	 * there are only a couple of choices, and it shows the alternative without a click.
	 */
	static JPanel segmented(String[] labels, int selectedIndex, IntConsumer onSelect)
	{
		JPanel row = new JPanel(new GridLayout(1, labels.length, 4, 0));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));

		ButtonGroup group = new ButtonGroup();

		for (int i = 0; i < labels.length; i++)
		{
			final int index = i;
			JToggleButton option = new JToggleButton(labels[i]);
			option.setFont(FontManager.getRunescapeSmallFont());
			option.setFocusPainted(false);
			option.setBorder(BorderFactory.createEmptyBorder(4, 2, 4, 2));
			option.setSelected(i == selectedIndex);
			paintToggle(option);

			option.addItemListener(event ->
			{
				paintToggle(option);
				if (option.isSelected())
				{
					onSelect.accept(index);
				}
			});

			group.add(option);
			row.add(option);
		}

		return row;
	}

	private static void paintToggle(JToggleButton option)
	{
		option.setBackground(option.isSelected()
			? Theme.GOLD
			: Theme.CARD);
		option.setForeground(option.isSelected()
			? Theme.CARD
			: Theme.TEXT);
	}

	/**
	 * Keeps the dropdown popup dark instead of the default white list.
	 */
	private static final class DarkListRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(
			JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
		{
			super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);

			setFont(FontManager.getRunescapeSmallFont());
			setBackground(isSelected ? Theme.GOLD : Theme.CARD);
			setForeground(isSelected ? Theme.CARD : Theme.TEXT);
			setBorder(BorderFactory.createEmptyBorder(3, 5, 3, 5));
			return this;
		}
	}

	/**
	 * Item names come from the game and can contain characters that would break the HTML wrapper.
	 */
	static String escape(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package com.botw.ui;

import com.botw.data.Challenge;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.TimeUnit;

/**
 * How long until a challenge starts, or until it ends once it has.
 * <p>
 * The one question anyone opening this panel has, and it changes meaning halfway through the week
 * without the player doing anything. Kept apart from the panels so both of them phrase it the same
 * way.
 */
public final class Countdown
{
	private Countdown()
	{
	}

	/**
	 * A single line for the top of a challenge: what is being waited for, and how long.
	 */
	public static String describe(Challenge challenge, long now)
	{
		if (!challenge.hasStarted(now))
		{
			return "Starts in " + remaining(challenge.getStartsAt() - now);
		}

		if (!challenge.hasEnded(now))
		{
			return "Ends in " + remaining(challenge.getEndsAt() - now);
		}

		return "Finished";
	}

	/**
	 * Coarse on purpose. Nobody planning a week of bossing needs the seconds, and a figure that
	 * reprints every second is harder to read, not easier.
	 */
	public static String remaining(long millis)
	{
		if (millis <= 0)
		{
			return "moments";
		}

		long days = TimeUnit.MILLISECONDS.toDays(millis);
		long hours = TimeUnit.MILLISECONDS.toHours(millis) % 24;
		long minutes = TimeUnit.MILLISECONDS.toMinutes(millis) % 60;

		if (days > 0)
		{
			return days + (days == 1 ? " day " : " days ") + hours + "h";
		}

		if (hours > 0)
		{
			return hours + "h " + minutes + "m";
		}

		// Under an hour the minutes are what matter, and seconds only in the last stretch.
		if (minutes > 0)
		{
			return minutes + "m";
		}

		return TimeUnit.MILLISECONDS.toSeconds(millis) + "s";
	}

	/**
	 * A start or end time written in the timezone the creator chose, so what everyone reads is the
	 * time the creator meant rather than whatever their own machine is set to.
	 */
	public static String at(long epochMillis, String timezone)
	{
		ZoneId zone;
		try
		{
			zone = ZoneId.of(timezone);
		}
		catch (Exception e)
		{
			zone = ZoneId.systemDefault();
		}

		ZonedDateTime when = Instant.ofEpochMilli(epochMillis).atZone(zone);
		return when.format(DateTimeFormatter.ofPattern("d MMM, h:mma")) + " " + zone.getId();
	}
}

package com.botw.ui;

import com.botw.data.Challenge;
import com.botw.data.DropRule;
import com.botw.data.LeaderboardEntry;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
